LinkStack InitStack()
//空栈的 top 指针为 NULL
{ return NULL; }

int StackEmpty(LinkStack top)
//判栈为空栈时返回值为真, 反之为假
{ return (top == NULL? TRUE: FALSE); }

void Push(LinkStack top, Elemtype e)
{ //将元素 e 进链栈, 即在表头插入新的结点
    StackNode *s;
    s = (StackNode*)malloc(sizeof(StackNode));
    s->data = e;
    s->next = top;
    top = s;
}

int Pop(LinkStack top, Elemtype &e)
{ //若栈不为空将栈顶元素出栈, 即为删除表头结点
    StackNode *p;
    if (StackEmpty(top)) return ERROR; //栈空
    e = top->data;
    p = top;
    top = top->next;
    free(p);
    retrun OK;
}
